import{_ as s,l as i,o as e,c as n,v as o,p as l,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"PoW 与区块链共识直觉","description":"","frontmatter":{"title":"PoW 与区块链共识直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pow-blockchain-consensus.md","filePath":"cs/pow-blockchain-consensus.md","lastUpdated":1789023840000}'),h={name:"cs/pow-blockchain-consensus.md"};function P(B,a,_,m,f,E){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="pow-与区块链共识直觉" tabindex="-1">PoW 与区块链共识直觉 <a class="header-anchor" href="#pow-与区块链共识直觉" aria-label="Permalink to &quot;PoW 与区块链共识直觉&quot;">​</a></h1><div class="epigraph"><p>开放成员里没有 $n$ 与 $f$ 的名册。工作量证明让出块权变贵，最长链是一种概率最终的全序，不是 Paxos 的多数派选定。</p><footer>—— 据 Nakamoto, Bitcoin: A Peer-to-Peer Electronic Cash System, 2008；Lamport 拜占庭将军与 Castro PBFT 对照整理</footer></div><p>上一课<a href="/cs/etcd-chubby">etcd/Chubby</a>假定已知副本集。缺口是<strong>许可名单不存在</strong>时如何对日志达成序。本课只给计算机课需要的直觉：PoW 换了故障与同步假设，不把加密货币、交易所或限价簿写进来。共识单元在此封口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PBFT 要 \\(n=3f+1\\) 且身份已知。开放网络身份可伪造（Sybil）。Nakamoto：出块须找哈希低于目标，期望耗时由难度调节。后继块指针形成树，客户端跟<strong>累计工作最多</strong>的链。重组：更长（更重）的链让浅块失去最终性——最终性是概率随深度指数降，不是多数派证书。</p><p>缺口：这不是<a href="/cs/linearizability">线性一致</a>寄存器。读「最新块」可在分叉上。确认数是应用选的深度，不是 Herlihy–Wing 的线性化点。</p><p><span class="marginnote">2008 白皮书不是同行评审 TODS，但是 PoW 链的源头文献。Dwork–Naor 的定价邮件是 PoW 更早思想，点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表（直觉，不证经济）：</p><p>| | Raft/PBFT | PoW 链 | | 成员 | 已知 | 开放 | | 安全阈值 | \\(f\\) 相对 \\(n\\) | 算力比例 | | 最终性 | 提交后确定 | 深度概率 | | 同步 | 部分同步活性 | 出块间隔相对传播延迟 |</p>',10)),(e(),l(d,null,{default:t(()=>[c(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20POW%5B%22%E8%A7%A3%E5%93%88%E5%B8%8C%22%5D%20--%3E%20BLK%5B%22%E5%87%BA%E5%9D%97%22%5D%0A%20%20BLK%20--%3E%20CHAIN%5B%22%E6%8C%87%E9%92%88%E6%88%90%E9%93%BE%22%5D%0A%20%20FORK%5B%22%E5%88%86%E5%8F%89%22%5D%20--%3E%20W%5B%22%E6%9B%B4%E9%87%8D%E8%80%85%E8%B5%A2%22%5D%0A%20%20W%20--%3E%20PROB%5B%22%E6%B5%85%E5%9D%97%E5%8F%AF%E8%A2%AB%E9%87%8D%E7%BB%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>不要把挖矿当<a href="/cs/failure-detectors">故障检测器</a>。也不要把难度当 NTP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>传播延迟若接近出块间隔，分叉率上升，安全性依赖「诚实算力多数」加足够慢的出块。这是同步味道的假设，与 FLP 异步确定共识不是同一格子。自私挖矿等攻击说明激励与算法缠在一起——本课点名，不写博弈全文。</p><p>许可链用 PBFT 族更常见：成员又回来了。PoW 的课程序列价值是：共识不一定长成 prepare/accept。数据中心有名册时，用 Raft 比用 PoW 更符合故障模型。</p><p>本课不写智能合约、不写 Transformer、不写 LOB。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析奖励函数，不引入权益证明细节。不给投资建议。后课系统模式从 RPC 开始，默认仍在数据中心崩溃模型；只有需要开放成员全序时才回想到 PoW 的概率最终。</p><p>有名册，用法定人数。无名册，用昂贵的出块权加概率深度。不要把后者的话术套到 etcd。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PoW 抗 Sybil：出块耗能，最长（最重）链排序。</li><li>最终性是深度上的概率，不是多数派证书。</li><li>已知成员的数据中心协调仍用 Raft/Paxos/PBFT。</li><li>出处：Nakamoto, 2008；对照 Lamport BGP、Castro PBFT。</li></ul>',10))])}const b=s(h,[["render",P]]);export{T as __pageData,b as default};
